fn hx(comptime n: usize, comptime hex: []const u8) [n]u8 {
    @setEvalBranchQuota(1_000_000);
    var out: [n]u8 = undefined;
    _ = @import("std").fmt.hexToBytes(&out, hex) catch unreachable;
    return out;
}
